{
 "module_name": "Comparison Group Design",
 "goal": "基于样本信息表的分组信息，设计符合研究主题（高铁饮食对CDI小鼠肠道代谢的影响）的差异分析比对组对。共识别出3个生物学分组：NC（健康对照）、CD（艰难梭菌感染）、FE（感染前高铁饮食干预），并设计了3组两两比对以全面揭示高铁饮食调节CDI易感性的代谢物基础。",
 "input_files": [
 "G:/OmicsWorks/test/metabolism/sampleinfo.csv",
 "G:/OmicsWorks/test/metabolism/expression.csv",
 "G:/OmicsWorks/test/metabolism/demo/tmp/preprocessed_expression.csv"
 ],
 "output_files": [
 "G:/OmicsWorks/test/metabolism/demo/tmp/3_comparison_group_design/tables/comparison_design.csv",
 "G:/OmicsWorks/test/metabolism/demo/analysis/3_comparison_group_design/comparison_design_visualization.png"
 ],
 "execution_steps": [
 {
 "action": "解析样本信息表，提取各样本的分组归属，汇总分组统计信息",
 "goal": "明确可用的生物学分组（NC、CD、FE）及各组样本量，排除QC样本"
 },
 {
 "action": "基于研究主题和知识库中已知的生物学机制，设计3组两两比对（FE_vs_CD、CD_vs_NC、FE_vs_NC），记录每组比对的处理组、对照组、生物学依据和预期发现",
 "goal": "生成比对设计表 comparison_design.csv，作为后续LIMMA差异分析和KEGG GSVA分析的依据"
 },
 {
 "action": "编写R脚本生成比对结构可视化图，展示各组间比对关系",
 "goal": "生成直观的比对设计示意图，便于理解分析策略"
 }
 ],
 "comparisons": [
 {
 "name": "FE_vs_CD",
 "treatment": "high iron diet before",
 "control": "Clostridium difficile infection",
 "biological_rationale": "这是本研究的核心比对。FE组与CD组均感染了艰难梭菌，唯一区别在于FE组在感染前接受了高铁饮食干预。此比对可直接揭示高铁饮食对CDI感染状态下肠道代谢组的调节作用，包括铁稳态相关代谢物、胆汁酸、短链脂肪酸等关键代谢物的差异。根据知识库，高铁饮食预计会促进C.difficile生长和毒素产生（通过FeoAB、Fhu、Fur系统），上调tcdA/tcdB表达，同时改变宿主营养免疫（calprotectin、lipocalin-2）和胆汁酸代谢谱。",
 "expected_findings": "预期可观察到：①铁稳态相关代谢物（血红素、铁载体、转铁蛋白）显著上调；②结合型胆汁酸（牛磺胆酸盐等促孢子萌发代谢物）升高，去结合型胆汁酸（胆酸盐等抑制性代谢物）降低；③短链脂肪酸（尤其是丁酸）显著降低，反映产SCFA有益菌减少；④肠杆菌科相关的铁载体代谢物升高；⑤糖酵解/Stickland发酵相关代谢物比例改变，反映C.difficile代谢重编程；⑥嘌呤/嘧啶代谢物变化反映细菌增殖加速。"
 },
 {
 "name": "CD_vs_NC",
 "treatment": "Clostridium difficile infection",
 "control": "Standard (control)",
 "biological_rationale": "此比对为模型验证比对，用于建立艰难梭菌感染本身的代谢组特征基线。CD组为感染C.difficile的标准饲料小鼠，NC组为未感染的健康对照。此比对可验证CDI模型是否成功建立，并揭示感染引起的核心代谢紊乱特征，包括胆汁酸代谢紊乱（结合型胆汁酸升高、去结合型胆汁酸降低）、SCFA减少、宿主营养免疫应答相关的代谢物变化等。这些变化与知识库中描述的CDI致病机制（TcdA/TcdB毒素作用、孢子萌发调节、肠道菌群失调）一致。",
 "expected_findings": "预期可观察到：①艰难梭菌感染导致的典型代谢紊乱特征，如胆汁酸谱偏移（牛磺胆酸盐升高、胆酸盐降低）；②短链脂肪酸（乙酸、丙酸、丁酸）水平下降，反映菌群失调；③炎症相关代谢物（如前列腺素类、ROS相关代谢物）升高；④宿主营养免疫相关代谢物（calprotectin相关金属螯合物、lipocalin-2底物）变化；⑤肠上皮损伤标志物（如I-FABP相关代谢物）可能升高。"
 },
 {
 "name": "FE_vs_NC",
 "treatment": "high iron diet before",
 "control": "Standard (control)",
 "biological_rationale": "此比对用于评估高铁饮食干预联合CDI感染相对于健康基线的整体代谢扰动幅度。与CD_vs_NC比对结合分析，可以区分哪些代谢变化是CDI感染本身引起的，哪些是高铁饮食叠加效应导致的。这有助于揭示"饮食-菌群-宿主"相互作用中，高铁饮食如何通过调节肠道微生态（促进肠杆菌科富集、减少乳酸杆菌/双歧杆菌）和宿主免疫（增强calprotectin释放、改变铁载体代谢）来改变CDI易感性。",
 "expected_findings": "预期可观察到：①代谢扰动幅度大于CD_vs_NC比对，反映高铁饮食的叠加效应；②铁相关代谢物（血红素、铁载体、含铁酶类底物）显著高于CD组；③胆汁酸代谢紊乱程度加剧，促孢子萌发的牛磺胆酸盐进一步升高；④SCFA水平进一步降低，反映高铁饮食对有益菌的额外抑制；⑤肠杆菌科相关的腐败代谢物（如胺类、酚类）升高；⑥可能观察到与铁毒性相关的氧化应激代谢物升高。"
 }
 ],
 "notes": "1. QC样本（Fc16YH_QC01~QC03）仅用于质控评估，不参与任何生物学比对分析。\n2.所有3个生物学分组（NC、CD、FE）均有6个生物学重复，统计效力充足。\n3.数据集为横截面设计（单时间点），无时间序列比对。\n4.比对结果将直接输入下游模块4（LIMMA差异分析）和模块5（KEGG GSVA差异分析）。\n5.建议在LIMMA分析中使用Benjamini-Hochberg FDR校正，显著阈值设为adj.P.Val<0.05且|log2FC|>1。\n6. FE_vs_CD为最核心比对，在结果解读中应优先关注；CD_vs_NC作为模型验证；FE_vs_NC作为整体效应评估。"
}

